const $=id=>document.getElementById(id),names={reference:'Reference pair',das:'Delay-and-sum',mvdr_known:'MVDR · known direction',mvdr_estimated:'MVDR · estimated direction',mvdr_rnnoise:'Known MVDR + RNNoise',neural_mvdr:'Neural mask MVDR · offline'},avg=x=>x.reduce((a,b)=>a+b,0)/x.length,fmt=(v,n=3)=>Number.isFinite(v)?v.toFixed(n):'—';
try{
const [d,l,n]=await Promise.all(['perceptual-evaluation.json','localization-evaluation.json','neural-beamformer-runtime.json'].map(async f=>{const r=await fetch(f);if(!r.ok)throw Error(f+': '+r.status);return r.json();}));
$('status').textContent=`${d.complete?'Complete':'PARTIAL RUN'} · ${d.completed_rows} / 96 method-scene rows · ${new Set(d.rows.map(r=>r.speaker)).size} speakers. ${d.complete?'Recorded results; filters do not rerun inference.':'Some conditions are missing; do not rank methods from this partial export.'}`;
for(const s of [...new Set(d.rows.map(r=>r.speaker))]){const o=document.createElement('option');o.value=s;o.textContent=s;$('speaker').append(o);}
function selected(){return d.rows.filter(r=>($('room').value==='all'||+($('room').value)===r.nominal_rt60_s)&&($('snr').value==='all'||+($('snr').value)===r.snr_left_db)&&($('speaker').value==='all'||$('speaker').value===r.speaker));}
function values(rows,fn){return [...new Set(rows.map(r=>r.speaker))].map(s=>{const a=rows.filter(r=>r.speaker===s).map(fn).filter(Number.isFinite);return a.length?avg(a):NaN;}).filter(Number.isFinite);}
function measure(rows,fn){const a=values(rows,fn);return a.length?avg(a):NaN;}
function draw(){const rows=selected();$('scores').innerHTML=Object.entries(names).map(([m,label])=>{const r=rows.filter(x=>x.method===m),h=measure(r,x=>avg(x.ears.map(e=>e.haspi_v2)));return `<tr><td>${label}</td><td><span class="metricbar" style="width:${Number.isFinite(h)?Math.max(0,Math.min(100,h*100)):0}px"></span>${fmt(h)}</td><td>${fmt(measure(r,x=>avg(x.ears.map(e=>e.hasqi_v2))))}</td><td>${fmt(measure(r,x=>avg(x.ears.map(e=>e.si_sdr_db))),2)}</td><td>${fmt(measure(r,x=>x.ild_error_db),2)}</td><td>${fmt(measure(r,x=>x.itd_error_us),1)}</td><td>${r.length}</td></tr>`;}).join('');
$('distortion').innerHTML=Object.entries(names).map(([m,label])=>{const r=rows.filter(x=>x.method===m),range=k=>{const a=values(r,x=>avg(x.ears.map(e=>e[k])));return a.length?`${fmt(Math.min(...a))}–${fmt(Math.max(...a))}`:'—';};return `<tr><td>${label}</td><td>${range('haspi_v2')}</td><td>${range('hasqi_v2')}</td><td>${fmt(measure(r,x=>x.target_only?avg(x.target_only.si_sdr_db):NaN),2)}</td><td>${fmt(measure(r,x=>x.target_only?avg(x.target_only.level_change_db):NaN),2)}</td><td>${fmt(measure(r,x=>avg(x.ears.map(e=>e.output_level_change_db))),2)}</td></tr>`;}).join('');
const a=rows.filter(r=>r.method==='mvdr_estimated');$('doaSummary').textContent=`In the selected room scenes, the four-microphone estimator has ${fmt(measure(a,x=>x.doa_mean_absolute_error_deg),1)}° mean absolute error and ${fmt(100*measure(a,x=>x.doa_within_10deg_fraction),1)}% of updates within 10° of the target after initial 0.5 s. A dominant-direction estimator can follow the masker.`;}
for(const id of ['room','snr','speaker'])$(id).addEventListener('change',draw);draw();
$('audio').innerHTML=d.rows.filter(r=>r.audio).map(r=>`<article><strong>${names[r.method]}</strong><p><audio controls preload="none" src="${r.audio}"></audio></p><a href="${r.audio}" download>Download WAV</a></article>`).join('');
$('localization').innerHTML=l.rows.map(r=>`<tr><td>${r.scenario.replaceAll('_',' ')}</td><td>${r.channels}</td><td>${r.sector_half_width_deg}</td><td>${fmt(r.mean_absolute_error_deg,1)}</td><td>${fmt(r.within_10deg_fraction*100,1)}%</td><td>${fmt(r.accepted_update_fraction*100,1)}%</td><td>${r.first_accepted_10deg_after_step_ms===null?'—':fmt(r.first_accepted_10deg_after_step_ms,1)}</td></tr>`).join('');
const keys=['stft_ms','network_and_mask_ms','covariance_and_solve_ms','istft_ms','total_ms'];$('runtime').innerHTML=`<p>Model: MetricGAN+ · ${n.provenance.parameters.toLocaleString()} parameters · ${(n.provenance.parameter_bytes/1048576).toFixed(2)} MiB parameter tensors. Load once: ${fmt(n.provenance.load_ms,2)} ms. These are CPU host measurements, not your browser.</p><div class="scroll"><table><thead><tr><th>Component</th><th>Mean ms / 3 s clip</th><th>Max ms</th></tr></thead><tbody>${keys.map(k=>`<tr><td>${k.replaceAll('_',' ').replace(' ms','')}</td><td>${fmt(avg(n.rows.map(r=>r.timings[k])),2)}</td><td>${fmt(Math.max(...n.rows.map(r=>r.timings[k])),2)}</td></tr>`).join('')}</tbody></table></div><p>Mean offline RTF: ${fmt(avg(n.rows.map(r=>r.rtf)),4)}. Full-utterance context: 3 seconds. Neural process peak RSS: ${(n.peak_process_rss_bytes/1048576).toFixed(1)} MiB (runtime, model and activations). Largest scoring-worker RSS: ${(d.peak_process_rss_bytes/1048576).toFixed(1)} MiB (includes auditory metrics; not neural model memory; simultaneous workers require more total memory).</p>`;
}catch(e){$('status').textContent='Could not load evaluation files: '+e.message;}

// Version 0.5: tracking controllers and closed-loop feedback cancellation.
try{const [t,f]=await Promise.all(['tracking-evaluation.json','feedback-evaluation.json'].map(async u=>{const r=await fetch(u);if(!r.ok)throw Error(u+': '+r.status);return r.json();}));
const label={known:'Known direction (upper bound)',dominant:'Dominant SRP (v0.4 estimated)',track_lock:'Tracker · lock-on',track_speech:'Tracker · speech-like'},cell=v=>`<td>${v}</td>`;
$('tracking').innerHTML=t.rows.filter(r=>r.method!=='reference').map(r=>`<tr>${cell(r.scenario.replaceAll('_',' '))}${cell(label[r.method]??r.method)}${cell(fmt(r.snr_gain_vs_reference_db[0],2))}${cell(fmt(r.mean_abs_error_deg,1))}${cell(Math.round(100*r.within_10deg_fraction)+'%')}${cell(Math.round(100*r.nearer_masker_fraction)+'%')}</tr>`).join('');
const cname={no_afc:'None',nlms:'Plain NLMS',nlms_shift6hz:'NLMS + 6 Hz shift',pem:'PEM-AFC'},edge=Math.max(...f.gains_db);
$('feedback').innerHTML=Object.keys(f.inputs).flatMap(i=>Object.keys(f.conditions).map(c=>{const m=f.max_stable_path_gain_db[i][c],row=f.rows.find(r=>r.input===i&&r.condition===c&&r.path_gain_db===-20);return `<tr>${cell(i.replaceAll('_',' '))}${cell(cname[c]??c)}${cell(m===null?'unstable at every gain':m===edge?`+${m} (edge)`:m+' dB')}${cell(row.stable?fmt(row.tail_level_change_db,1)+' dB':'howling')}</tr>`;})).join('');
const zero=(f.delay_ablation??[]).filter(r=>r.forward_delay_ms===0),ok=(f.delay_ablation??[]).filter(r=>r.forward_delay_ms>0);$('v05note').textContent=zero.length?`Forward-delay ablation (PEM): ${zero.filter(r=>!r.stable).length}/${zero.length} cases howl at 0 ms; ${ok.filter(r=>r.stable).length}/${ok.length} are stable with 1–4 ms. Any canceller needs forward-path delay to separate feedback from incoming sound.`:'';
}catch(e){$('tracking').innerHTML=`<tr><td colspan="6">Could not load v0.5 results: ${e.message}</td></tr>`;}
